pub fn contains(table: []const Range, cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (cp < table[mid].first) hi = mid else if (cp > table[mid].last) lo = mid + 1 else return true;
    }
    return false;
}
